practice.solution:
#include <iostream>
#include <string>

std::string repeatToken(int count)
{
    std::string result;
    for (int i{0}; i < count; ++i)
        result += "go ";
    return result;
}

int main()
{
    for (int count{0}; count <= 2; ++count)
        std::cout << '[' << repeatToken(count) << ']' << '\n';
    return 0;
}

