#define main learner_main
#include "main.cpp"
#undef main
#include <iostream>
#include <string>

int main()
{
    int failures{};
    for (int count{0}; count <= 100; ++count)
    {
        const std::string actual{repeatToken(count)};
        const auto expectedSize{static_cast<std::string::size_type>(count) * 3};
        bool correct{actual.size() == expectedSize};
        for (std::string::size_type pos{0}; pos < actual.size(); ++pos)
        {
            const char expected{pos % 3 == 0 ? 'g' : pos % 3 == 1 ? 'o' : ' '};
            if (actual[pos] != expected) correct = false;
        }
        if (!correct)
        {
            std::cerr << "Wrong repetition string for count=" << count
                      << " (expected size " << expectedSize
                      << ", got " << actual.size() << ")\n";
            ++failures;
        }
    }
    if (repeatToken(2) != "go go " || !repeatToken(0).empty() || repeatToken(1) != "go ")
    {
        std::cerr << "Repeated calls must not retain text from earlier calls\n";
        ++failures;
    }
    return failures == 0 ? 0 : 1;
}

